"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[4590],{85537:e=>{e.exports=JSON.parse('{"functions":[{"name":"Install","desc":"Wire the binding into GroundItemService.\\n\\n`static_assets` and `folder` are parameters rather than module-level\\n`workspace` lookups so this can be pointed at a fixture, and so requiring\\nthe module does not itself depend on the place being loaded.","params":[{"name":"static_assets","desc":"","lua_type":"Instance"},{"name":"folder","desc":"","lua_type":"Instance"}],"returns":[],"function_type":"method","source":{"line":189,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemBinding.luau"}},{"name":"InstallDefault","desc":"Install against the standard place layout.\\n\\nReturns false when the expected instances are missing, which is a place-file\\nor sync problem rather than a code one -- see the note in CLAUDE.md about\\ntrees that live only in the gitignored place.","params":[],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":222,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemBinding.luau"}}],"properties":[],"types":[],"name":"GroundItemBinding","desc":"The Roblox half of GroundItemService.\\n\\nEverything here needs a running place: a part pool, a raycast, attributes on\\nan instance, a CollectionService tag. Keeping it in its own module is what\\nlets `GroundItemService` -- the merging, the conservation, the spatial index\\n-- be tested headless.\\n\\nNothing requires this module implicitly. The server boot calls `Install`,\\nand until it does, ground piles exist and behave correctly but have no\\nvisible representation.","source":{"line":17,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemBinding.luau"}}')}}]);